import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Prop,
	h,
} from "@stencil/core";

/**
 * @since 2.0.1
 * @status stable
 *
 * @slot - The list container's content.
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-list",
	styleUrl: "list.scss",
	shadow: true,
})
export class HbrList {
	@Element() host: HTMLHbrListElement;

	/** The list container styles like "outline" or "list". */
	@Prop({ reflect: true, mutable: true }) variant:
		| "outline"
		| "list"
		| "interactive";

	/** The list container size. since v2.15.1.
	 * Moving from "xl", "lg", "md", "sm" to "xlarge", "large", "medium", "small" */
	@Prop({ reflect: true }) size: "xlarge" | "large" | "medium" | "small" =
		"medium";

	/** The Ordered List "ol" element. */
	@Prop({ reflect: true }) ordered: boolean;

	@Prop() arialabel: string;

	/** Indicates used as an anchor link menu. */
	@Prop({ reflect: true }) anchor: boolean;

	/** Indicates used as a nested list. */
	@Prop({ reflect: true }) nested: boolean;

	/** The list container spacing. since v2.14.12 */
	@Prop({ reflect: true }) spacing: "compact" | "spacious" = "compact";

	/** Emitted when clicking the list. */
	@Event({ eventName: "hbr-click" }) hbrClick: EventEmitter;

	private clickTarget: HTMLElement;

	private handleClick(event: Event) {
		const target = event.target as HTMLElement;
		const listItem = target.closest("hbr-list-item");
		if (!listItem) {
			return;
		}

		//
		// Don't Do anything if there's no list item, if it's disabled, or if the click doesn't match the initial target
		// from mousedown. The latter case prevents the user from starting a click on one item and ending it on another,
		// causing the parent node to collapse.
		//
		if (!listItem || listItem.disabled || target !== this.clickTarget) {
			return;
		}
		this.hbrClick.emit();
	}

	handleMouseDown(event: MouseEvent) {
		// Record the click target so we know which item the click initially targeted
		this.clickTarget = event.target as HTMLHbrListElement;
	}

	private handleKeyDown(event: KeyboardEvent) {
		// Ignore key presses we aren't interested in
		if (
			![
				"ArrowDown",
				"ArrowUp",
				"ArrowRight",
				"ArrowLeft",
				"Home",
				"End",
				"Enter",
				" ",
			].includes(event.key)
		) {
			return;
		}

		// Ignore key presses when focus is inside a text field. This prevents the component from hijacking nested form
		// controls that exist inside tree items.
		// if (
		// 	event
		// 		.composedPath()
		// 		.some((el: HTMLElement) =>
		// 			["input", "textarea"].includes(el?.tagName?.toLowerCase()),
		// 		)
		// ) {
		// 	return;
		// }
	}

	render() {
		if (this.variant === "list") {
			return (
				<Host>
					<slot />
				</Host>
			);
		}
		const Tag = this.ordered ? "ol" : "ul";
		return (
			// due to the wrapper blocking for SR to read <li> be child of <ul>, we need to add the role to the host
			<Host role="list">
				<Tag
					part="base"
					role="presentation"
					class={{
						list: true,
						"list--outline": this.variant === "outline",
						"list--ordered": this.ordered,
						"list--anchor": this.anchor,
					}}
					{...(this.arialabel ? { "aria-label": this.arialabel } : {})}
					onClick={this.handleClick.bind(this)}
					onMouseDown={this.handleMouseDown.bind(this)}
					onKeyDown={this.handleKeyDown.bind(this)}
				>
					<div class="list__line" part="line" />
					<slot />
				</Tag>
			</Host>
		);
	}
}
